// Resolve assigned agent with backup fallback
const agentData = $input.first();
const enrichedData = $('Validate & Enrich').first().json;

let assignedAgent = 'Team Lead';
let assignedSlackId = '';
let assignedEmail = '';
let assignedRole = '';

try {
  const fields = agentData.json.fields || agentData.json;

  if (fields && fields['Agent Name']) {
    const isAvailable = fields['Is Available'];

    if (isAvailable) {
      assignedAgent = fields['Agent Name'] || 'Team Lead';
      assignedSlackId = fields['Slack User ID'] || '';
      assignedEmail = fields['Agent Email'] || '';
      assignedRole = fields['Role'] || '';
    } else {
      // Primary agent unavailable — use backup
      assignedAgent = fields['Backup Agent Name'] || 'Team Lead';
      assignedSlackId = fields['Backup Slack User ID'] || '';
      assignedRole = 'Backup';
    }
  }
} catch (err) {
  // No agent found — default to Team Lead
  assignedAgent = 'Team Lead';
  assignedSlackId = '';
}

// Build safe Slack mention — never output a broken <@> tag
// If we have a Slack ID: "<@U12345> (Maria Santos)"
// If we don't: "Maria Santos" or "Team Lead (unassigned)"
let slackMention;
if (assignedSlackId) {
  slackMention = '<@' + assignedSlackId + '> (' + assignedAgent + ')';
} else if (assignedAgent !== 'Team Lead') {
  slackMention = assignedAgent;
} else {
  slackMention = 'Team Lead (unassigned)';
}

return [{
  json: {
    ...enrichedData,
    assignedAgent,
    assignedSlackId,
    assignedEmail,
    assignedRole,
    slackMention
  }
}];

// Validate AI Agent output and enrich with metadata
const item = $input.first();
const airtableRecord = $('Log to Airtable').first();
const recordId = airtableRecord.json.id;
const original = $('Extract Message Data').first().json;

let result;

try {
  // The AI Agent with Structured Output Parser returns parsed JSON in .output
  const parsed = item.json.output || item.json;

  // Validate category against allowed values
  const validCategories = [
    'Billing', 'Access', 'Scheduling',
    'Technical Support', 'General Question', 'Refund Request'
  ];

  let category = parsed.category || 'General Question';
  let confidence = typeof parsed.confidence === 'number' ? parsed.confidence : 0;
  let needsHumanReview = parsed.needs_human_review === true;
  let reasoning = parsed.reasoning || '';
  let draftResponse = parsed.draft_response || '';

  // Auto-correct invalid category
  if (!validCategories.includes(category)) {
    category = 'General Question';
    needsHumanReview = true;
    reasoning += ' [Auto-corrected: AI returned invalid category]';
  }

  // Clamp confidence to valid range
  if (confidence < 0 || confidence > 100) {
    confidence = 0;
    needsHumanReview = true;
  }

  result = {
    recordId: recordId,
    category: category,
    confidence: Math.round(confidence),
    needsHumanReview: needsHumanReview,
    reasoning: reasoning,
    draftResponse: draftResponse,
    status: 'Classified',
    error: false,
    senderEmail: original.senderEmail,
    senderName: original.senderName,
    subject: original.subject
  };

} catch (err) {
  // Fallback: ensure message still gets human attention
  result = {
    recordId: recordId,
    category: 'General Question',
    confidence: 0,
    needsHumanReview: true,
    reasoning: 'AI Agent output validation failed: ' + err.message + '. Routed to human review.',
    draftResponse: '',
    status: 'Error',
    error: true,
    senderEmail: original.senderEmail,
    senderName: original.senderName,
    subject: original.subject
  };
}

return [{ json: result }];

// Extract and normalize message data (Gmail Trigger format)
const items = $input.all();
const results = [];

for (const item of items) {
  const email = item.json;

  // Gmail uses 'id' not 'messageId'
  const messageId = email.id || '';

  // Parse 'From' (capital F) — comes as "Name <email@domain.com>"
  const fromRaw = email.From || '';
  let senderEmail = '';
  let senderName = 'Unknown';

  const emailMatch = fromRaw.match(/<(.+?)>/);
  if (emailMatch) {
    senderEmail = emailMatch[1];
    senderName = fromRaw.replace(/<.+?>/, '').trim() || 'Unknown';
  } else {
    senderEmail = fromRaw.trim();
  }

  // Gmail uses 'Subject' (capital S)
  const subject = email.Subject || '(No Subject)';

  // Body: use snippet (Gmail preview text) as primary source
  let body = email.snippet || '';
  body = body.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
  if (body.length > 3000) {
    body = body.substring(0, 3000) + '\n[... truncated for processing]';
  }

  // Convert internalDate to both formats
  const dateObj = email.internalDate
    ? new Date(parseInt(email.internalDate))
    : new Date();

  // ISO format for Airtable date field
  const receivedAt = dateObj.toISOString();

  // Human-readable format for display
  const month = String(dateObj.getMonth() + 1).padStart(2, '0');
  const day = String(dateObj.getDate()).padStart(2, '0');
  const year = dateObj.getFullYear();
  let hours = dateObj.getHours();
  const minutes = String(dateObj.getMinutes()).padStart(2, '0');
  const ampm = hours >= 12 ? 'PM' : 'AM';
  hours = hours % 12 || 12;
  const receivedAtFormatted = `${month}-${day}-${year} ${hours}:${minutes} ${ampm}`;

  results.push({
    json: {
      messageId: messageId,
      receivedAt: receivedAt,
      receivedAtFormatted: receivedAtFormatted,
      senderEmail: senderEmail,
      senderName: senderName,
      subject: subject,
      body: body
    }
  });
}

if (results.length === 0) {
  results.push({ json: { _skip: true } });
}

return results;

